// ──────────────────────────── tests ──────────────────────────────────────

test('config: missing, undefined and null overrides fall back', () => {
  const defaults = { docks: 12, label: 'Main', radiusKm: 5, debug: true };
  eq(mergeKioskConfig(defaults, { label: undefined, radiusKm: null }), {
    docks: 12,
    label: 'Main',
    radiusKm: 5,
    debug: true,
  });
});

test('config: 0, the empty string and false survive the merge', () => {
  const defaults = { docks: 12, label: 'Main', radiusKm: 5, debug: true };
  eq(mergeKioskConfig(defaults, { docks: 0, label: '', debug: false }), {
    docks: 0,
    label: '',
    radiusKm: 5,
    debug: false,
  });
});

test('dock label: reads a nested field and fills the gaps', () => {
  eq(formatDock({ dockId: 3, bike: { code: 'B9' } }), 'dock 3 · B9');
  eq(formatDock({ dockId: 4 }), 'dock 4 · empty');
});

test('dock label: called with no argument at all, it still answers', () => {
  eq(formatDock(), 'dock ? · empty');
});

test('counters: count from 1 and never share a total', () => {
  const a = makeDockCounter();
  const b = makeDockCounter();
  eq([a(), a(), a()], [1, 2, 3]);
  eq(b(), 1);
  eq(a(), 4);
});

test('status table: known codes map, inherited names do not', () => {
  eq(bikeStatus('free'), 'ready');
  eq(bikeStatus('rented'), 'in use');
  eq(bikeStatus('broken'), 'needs service');
  eq(bikeStatus('parked'), 'unknown');
  eq(bikeStatus('toString'), 'unknown');
  eq(bikeStatus('constructor'), 'unknown');
});

test('tag parsing: splits pairs, keeps empties, skips junk', () => {
  eq(parseKioskTag('id=7;city=oslo;lock='), {
    id: '7',
    city: 'oslo',
    lock: '',
  });
  eq(parseKioskTag('id=7;;broken;city=oslo'), { id: '7', city: 'oslo' });
  eq(parseKioskTag('note=a=b'), { note: 'a=b' });
  eq(parseKioskTag(''), {});
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a method pulled off its object still finds its receiver', () => {
  const register = makeRegister();
  const ring = detachRing(register);
  eq(ring(3), 'front: 3');
  eq(register.taken, 3);
});

test('and it tracks the object, not a snapshot of it', () => {
  const register = makeRegister();
  const ring = detachRing(register);
  ring(3);
  register.name = 'back';
  eq(ring(2), 'back: 5');
});

test('orders tally by pastry', () => {
  eq(countByPastry(ORDERS), { croissant: 3, baguette: 1, danish: 2 });
  eq(countByPastry([]), {});
});

test('the queue sorts by hour, then by name', () => {
  eq(sortOrders(ORDERS).map((o) => o.id), ['o4', 'o2', 'o1', 'o6', 'o3', 'o5']);
});

test('sorting returns a new array and leaves the frozen one alone', () => {
  const sorted = sortOrders(ORDERS);
  eq(ORDERS.map((o) => o.id), ['o1', 'o2', 'o3', 'o4', 'o5', 'o6']);
  eq(sorted === ORDERS, false);
});

test('a rejected bake comes back as a value, not a rejection', async () => {
  eq(await safeBake(async () => 'loaf'), { ok: true, value: 'loaf' });
  eq(
    await safeBake(async () => {
      throw new Error('oven cold');
    }),
    { ok: false, error: 'oven cold' }
  );
});

test('the busiest hour breaks ties in favour of the earlier one', () => {
  eq(busiestHour(ORDERS), 9);
  eq(
    busiestHour([
      { hour: 14 },
      { hour: 8 },
      { hour: 14 },
      { hour: 8 },
      { hour: 6 },
    ]),
    8
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

test('each labeler describes its own route, not the last one', () => {
  const labelers = makeRouteLabelers(ROUTES);
  eq(labelers.length, 5);
  eq(labelers[0](), 'Slab Waltz (V2)');
  eq(labelers[2](), 'Arete Dance (V2)');
  eq(labelers[4](), 'Warm Up Jugs (V0)');
});

test('routes bucket by grade, in source order', () => {
  const groups = groupByGrade(ROUTES);
  eq(Object.keys(groups), ['V2', 'V5', 'V0']);
  eq(groups.V2.map((r) => r.id), ['r1', 'r3']);
  eq(groups.V5.map((r) => r.id), ['r2', 'r4']);
});

test('a promotion returns a new gym carrying the new tier', () => {
  const after = promoteMember(GYM, 'm1', 'pro');
  eq(after.members.m1.plan.tier, 'pro');
  eq(after.members.m1.plan.months, 3);
  eq(after.name, 'Northwall');
});

test('the frozen original is untouched', () => {
  promoteMember(GYM, 'm1', 'pro');
  eq(GYM.members.m1.plan.tier, 'basic');
});

test('branches that did not change are shared, not copied', () => {
  const after = promoteMember(GYM, 'm1', 'pro');
  ok(after !== GYM, 'the gym itself is a new object');
  ok(after.members !== GYM.members, 'the changed path is cloned');
  ok(after.members.m2 === GYM.members.m2, 'untouched members are shared');
});

test('the first entry wins for each tag', () => {
  eq(
    dedupeByTag([
      { tag: 'beta', note: 'heel hook' },
      { tag: 'warn', note: 'loose hold' },
      { tag: 'beta', note: 'toe hook' },
      { tag: 'warn', note: 'chalk up' },
    ]),
    [
      { tag: 'beta', note: 'heel hook' },
      { tag: 'warn', note: 'loose hold' },
    ]
  );
  eq(dedupeByTag([]), []);
});

test('kebab-case survives spaces, camelCase and punctuation', () => {
  eq(toKebab('Slab Waltz'), 'slab-waltz');
  eq(toKebab('roofRodeo'), 'roof-rodeo');
  eq(toKebab('Slab  Waltz!'), 'slab-waltz');
  eq(toKebab('V5 Roof'), 'v5-roof');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('saved zeros and falses beat the defaults', () => {
  eq(playerSettings({ volume: 0, autoplay: false, skipIntroSec: 45 }), {
    speed: 1,
    volume: 0,
    autoplay: false,
    skipIntroSec: 45,
  });
});

test('missing keys — and a missing object — fall back', () => {
  const defaults = { speed: 1, volume: 0.8, autoplay: true, skipIntroSec: 0 };
  eq(playerSettings({}), defaults);
  eq(playerSettings(), defaults);
  eq(playerSettings({ speed: undefined }), defaults);
});

test('the timer keeps working after its methods are pulled apart', () => {
  const { tick, label } = makeEpisodeTimer('Ep 12');
  tick(30);
  tick(15);
  eq(label(), 'Ep 12 @ 45s');
});

test('building an instance by hand links the prototype', () => {
  const host = construct(Host, ['Ada']);
  ok(host instanceof Host);
  eq(host.name, 'Ada');
  eq(host.shows, []);
  eq(host.greet(), 'hi from Ada');
});

test('a constructor that returns an object wins', () => {
  eq(construct(Swapped, []), { swapped: true });
});

test('every episode is awaited, and results keep input order', async () => {
  const fetchOne = (id) =>
    new Promise((resolve) => setTimeout(() => resolve(`ep-${id}`), (4 - id) * 6));
  eq(await loadEpisodes([1, 2, 3], fetchOne), ['ep-1', 'ep-2', 'ep-3']);
  eq(await loadEpisodes([], fetchOne), []);
});

test('the index answers in both directions, and misses cleanly', () => {
  const ix = makeShowIndex(SHOWS);
  eq(ix.idFor('deep-dive'), 's2');
  eq(ix.slugFor('s2'), 'deep-dive');
  eq(ix.idFor('no-such-show'), undefined);
  eq(ix.slugFor('toString'), undefined);
});

