test('zero rounds and an empty tie-break survive; null does not', () => {
  eq(tournamentOptions({ rounds: 0, tieBreak: '', byePoints: null }), {
    rounds: 0,
    rated: true,
    tieBreak: '',
    byePoints: 0.5,
  });
  eq(tournamentOptions({ rated: false }).rated, false);
});

test('anything the saved settings skip comes from the defaults', () => {
  const defaults = {
    rounds: 7,
    rated: true,
    tieBreak: 'buchholz',
    byePoints: 0.5,
  };
  eq(tournamentOptions({}), defaults);
  eq(tournamentOptions(), defaults);
});

test('points tally over the crosstable', () => {
  eq(standings(GAMES), { Ada: 2.5, Bo: 0, Cyd: 1.5 });
  eq(standings([]), {});
});

test('the table sorts by points, then wins, then name', () => {
  eq(rankPlayers(PLAYERS).map((p) => p.name), [
    'Ada',
    'Dre',
    'Bo',
    'Cyd',
    'Eve',
  ]);
});

test('ranking leaves the frozen roster alone', () => {
  rankPlayers(PLAYERS);
  eq(PLAYERS.map((p) => p.name), ['Ada', 'Bo', 'Cyd', 'Dre', 'Eve']);
});

test('the piece table answers 0 for names it does not own', () => {
  eq(pieceValue('pawn'), 1);
  eq(pieceValue('rook'), 5);
  eq(pieceValue('queen'), 9);
  eq(pieceValue('duck'), 0);
  eq(pieceValue('valueOf'), 0);
  eq(pieceValue('hasOwnProperty'), 0);
});

test('time controls parse in both forms, and refuse nonsense', () => {
  eq(parseClock('90+30'), { baseMin: 90, incSec: 30 });
  eq(parseClock('5'), { baseMin: 5, incSec: 0 });
  eq(parseClock('3+2'), { baseMin: 3, incSec: 2 });
  eq(parseClock('blitz'), null);
  eq(parseClock('90+'), null);
  eq(parseClock(''), null);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the summary renames, defaults, and reaches into the stock', () => {
  eq(
    jobSummary({ jobTitle: 'Flyers', copies: 250, stock: { paper: 'gloss' } }),
    'Flyers ×250 on gloss'
  );
  eq(jobSummary({ jobTitle: 'Poster' }), 'Poster ×1 on plain');
  eq(jobSummary(), 'untitled ×1 on plain');
});

test('a report handed off as a bare callback still knows its press', () => {
  const press = new Press('A1');
  press.queue('flyers');
  press.queue('cards');
  const report = press.report;
  eq(report(), 'A1: 2 queued');
  const runLater = (fn) => fn();
  eq(runLater(press.report), 'A1: 2 queued');
});

test('once runs its function a single time and reuses the answer', () => {
  const warmUp = spy(() => 'warm');
  const guarded = once(warmUp);
  eq([guarded(), guarded(), guarded()], ['warm', 'warm', 'warm']);
  eq(warmUp.callCount, 1);
});

test('two wrappers around the same function keep separate state', () => {
  const warmUp = spy(() => 'warm');
  const a = once(warmUp);
  const b = once(warmUp);
  a();
  b();
  eq(warmUp.callCount, 2);
});

test('reassigning returns a new shop and shares what did not change', () => {
  const after = reassignJob(SHOP, 'j1', 'B2');
  eq(after.jobs.j1, { title: 'Flyers', press: 'B2', copies: 250 });
  eq(after.city, 'Leeds');
  ok(after.jobs.j2 === SHOP.jobs.j2, 'untouched jobs are shared');
});

test('the frozen shop is not touched', () => {
  reassignJob(SHOP, 'j1', 'B2');
  eq(SHOP.jobs.j1.press, 'A1');
});

test('the first task that works wins; all-failed reports the count', async () => {
  const boom = (why) => async () => {
    throw new Error(why);
  };
  eq(
    await firstSuccess([boom('press jammed'), async () => 'printed', boom('x')]),
    'printed'
  );
  await rejects(
    () => firstSuccess([boom('a'), boom('b'), boom('c')]),
    'all 3 failed'
  );
});

