test('debounce · nothing runs during the burst', () => {
  const write = spy();
  const save = debounce(write, 15);
  save('a');
  save('ab');
  eq(write.callCount, 0);
  eq(save('abc'), undefined, 'the wrapper answers later, not now');
});

test('debounce · one call lands after the quiet period, last args win', async () => {
  const write = spy();
  const save = debounce(write, 15);
  save('a');
  save('ab');
  save('abc');
  await sleep(35);
  eq(write.callCount, 1);
  eq(write.calls, [['abc']]);
});

test('debounce · a fresh burst after the first fire runs again', async () => {
  const write = spy();
  const save = debounce(write, 15);
  save('a');
  save('b');
  await sleep(35);
  save('c');
  await sleep(35);
  eq(write.calls, [['b'], ['c']]);
});

test('debounce · two wrappers keep separate timers', async () => {
  const first = spy();
  const second = spy();
  const a = debounce(first, 15);
  const b = debounce(second, 15);
  a('x');
  b('y');
  a('z');
  await sleep(35);
  eq(first.calls, [['z']]);
  eq(second.calls, [['y']]);
});

test('throttle · the first call goes straight through', () => {
  const send = spy();
  const ping = throttle(send, 20);
  ping('a', 1);
  eq(send.callCount, 1);
  eq(send.calls, [['a', 1]], 'every argument is forwarded');
});

test('throttle · calls inside the window are dropped, not queued', async () => {
  const send = spy();
  const ping = throttle(send, 20);
  ping('a');
  ping('b');
  ping('c');
  eq(send.callCount, 1);
  await sleep(30);
  eq(send.callCount, 1, 'a dropped call never fires late');
});

test('throttle · the window reopens after the interval', async () => {
  const send = spy();
  const ping = throttle(send, 20);
  ping('a');
  ping('b');
  await sleep(30);
  ping('c');
  eq(send.calls, [['a'], ['c']]);
});

test('throttle · two wrappers do not share a window', () => {
  const scroll = spy();
  const drag = spy();
  const onScroll = throttle(scroll, 20);
  const onDrag = throttle(drag, 20);
  onScroll('s');
  onDrag('d');
  onScroll('s2');
  eq(scroll.calls, [['s']]);
  eq(drag.calls, [['d']]);
  ok(typeof onScroll === 'function' && typeof onDrag === 'function');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('mapLimit · maps every item, in input order', async () => {
  resetTracker();
  eq(await mapLimit(['a', 'b', 'c', 'd'], 2, fetchOne), [
    'a0',
    'b1',
    'c2',
    'd3',
  ]);
});

test('mapLimit · stays under the limit and still uses all of it', async () => {
  resetTracker();
  await mapLimit(['a', 'b', 'c', 'd', 'e', 'f'], 2, fetchOne);
  ok(tracker.maxInFlight <= 2, `saw ${tracker.maxInFlight} in flight`);
  ok(tracker.maxInFlight === 2, 'a sequential loop wastes the budget');
});

test('mapLimit · an empty list resolves to an empty list', async () => {
  resetTracker();
  eq(await mapLimit([], 3, fetchOne), []);
  eq(tracker.maxInFlight, 0);
});

test('mapLimit · one rejection rejects the whole thing', async () => {
  const flaky = async (id) => {
    if (id === 'c') throw new Error('socket closed');
    return id;
  };
  await rejects(() => mapLimit(['a', 'b', 'c', 'd'], 2, flaky), 'socket closed');
});

test('LRU · set then get, and a miss stores nothing', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1);
  eq(cache.get('a'), 1);
  eq(cache.get('nope'), undefined);
  eq(cache.size(), 1);
});

test('LRU · over capacity, the least recently used key is evicted', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('c', 3);
  eq(cache.keys(), ['b', 'c']);
  eq(cache.get('a'), undefined);
  eq(cache.size(), 2);
});

test('LRU · a get counts as a use', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.get('a');
  cache.set('c', 3);
  eq(cache.keys(), ['a', 'c']);
  eq(cache.get('b'), undefined);
});

test('LRU · re-setting a key updates it and refreshes it', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('a', 99);
  eq(cache.keys(), ['b', 'a']);
  cache.set('c', 3);
  eq(cache.keys(), ['a', 'c']);
  eq(cache.get('a'), 99);
});

