test('search · finds both ends of a run', () => {
  eq(firstOccurrence([5, 7, 7, 8, 8, 10], 8), 3);
  eq(lastOccurrence([5, 7, 7, 8, 8, 10], 8), 4);
  eq(firstOccurrence([5, 7, 7, 8, 8, 10], 5), 0);
  eq(lastOccurrence([5, 7, 7, 8, 8, 10], 10), 5);
