export function makeRouteLabelers(routes) {
  return routes.map((route) => () => `${route.name} (${route.grade})`);
}

export function groupByGrade(routes) {
  return routes.reduce((groups, route) => {
    (groups[route.grade] ??= []).push(route);
    return groups;
  }, {});
}

