  const member = gym.members[memberId];
  return {
    ...gym,
    members: {
      ...gym.members,
      [memberId]: { ...member, plan: { ...member.plan, tier } },
    },
  };
}

export function dedupeByTag(entries) {
  const seen = new Set();
  const kept = [];
  for (const entry of entries) {
    if (seen.has(entry.tag)) continue;
    seen.add(entry.tag);
    kept.push(entry);
  }
  return kept;
}

