  const cache = new LRUCache(2);
  cache.set('a', 1);
  eq(cache.get('a'), 1);
  eq(cache.get('nope'), undefined);
  eq(cache.size(), 1);
});

test('LRU · over capacity, the least recently used key is evicted', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('c', 3);
  eq(cache.keys(), ['b', 'c']);
  eq(cache.get('a'), undefined);
  eq(cache.size(), 2);
});

test('LRU · a get counts as a use', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.get('a');
  cache.set('c', 3);
  eq(cache.keys(), ['a', 'c']);
  eq(cache.get('b'), undefined);
});

test('LRU · re-setting a key updates it and refreshes it', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('a', 99);
  eq(cache.keys(), ['b', 'a']);
  cache.set('c', 3);
  eq(cache.keys(), ['a', 'c']);
  eq(cache.get('a'), 99);
});

